        foreach ($allInventory as $catName => $products) {
            // Create Category
            $category = ProductCategory::updateOrCreate(
                ['slug' => Str::slug($catName)],
                [
                    'name_tr' => $catName,
                    'name_en' => $catName,
                    'is_active' => true,
                ]
            );

            foreach ($products as $p) {
                $sku = $p[0];
                $name = $p[1];
                $uName = $p[2];
                $rawPrice = $p[3];

                // Parse turkish price format (1.615,00) or (,558)
                // Remove thousand separators (.) and fix decimal separator (,)
                $sanitized = str_replace('.', '', $rawPrice);
                $sanitized = str_replace(',', '.', $sanitized);
                $unitPrice = floatval($sanitized);

                // Management of Units
                $unit = Unit::firstOrCreate(
                    ['symbol' => Str::ucfirst($uName)],
                    [
                        'name_tr' => $uName,
                        'name_en' => $uName,
                        'is_active' => true,
                    ]
                );

                Product::updateOrCreate(
                    ['sku' => (string)$sku],
                    [
                        'category_id' => $category->id,
                        'unit_id' => $unit->id,
                        'name_tr' => $name,
                        'name_en' => $name,
                        'unit_price' => $unitPrice,
                        'is_active' => true,
                        'track_quantity' => true,
                    ]
                );
            }
        }
